{
  "title": "The Mirror Bridge Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer studies a map of the ruined city.",
      "visual_description": "Mara unrolls a stained parchment map on a broken stone table; behind her, the ruined skyline of the royal city looms with tilted towers and faded banners.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "In a dark alley, the Oracle Lamp flickers on a crate, its single eye glowing; Mara and the Glass Diver lean in to listen.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The Tin Fox scampers ahead, reporting a patrol.",
      "visual_description": "The Tin Fox peeks around a collapsed wall, its blue glass eyes reflecting the gleam of armor plates moving in the distance.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The group hides as armored patrols march past.",
      "visual_description": "Mara, Glass Diver, Oracle Lamp and Tin Fox press against a cracked pillar while a column of metal-clad figures stomps by, banners snapping in the wind.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The Sleeping Tax Collector snores on a step.",
      "visual_description": "By the castle gates, the Sleeping Tax Collector dozes with a ledger under his head, stamped papers scattered around him like fallen leaves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara tries to wake the Tax Collector for keys.",
      "visual_description": "Mara shakes the Sleeping Tax Collector’s shoulder while the Oracle Lamp hovers nearby; the Tax Collector mumbles and turns over.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The Glass Diver finds a reflected key in a puddle.",
      "visual_description": "The Glass Diver kneels over a murky puddle, his helmet glinting as he reaches into the reflection and pulls out a rusted key.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The key opens a magic door in the castle wall.",
      "visual_description": "A stone archway glows as the key turns; the door dissolves into shimmering light, revealing a narrow corridor beyond.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "The Tin Fox detects a trap in the corridor.",
      "visual_description": "The Tin Fox stops, ears twitching, as faint pressure plates become visible on the floor tiles; blue light pulses from its tail.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Mara navigates the trap corridor with her map.",
      "visual_description": "Mara traces a route on her map with a compass; the group steps carefully over marked tiles, the Oracle Lamp casting shifting shadows.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "They enter a ruined throne room filled with old banners.",
      "visual_description": "Tattered royal banners hang from the ceiling, dust motes swirling; a broken throne sits at the far end, and a large mirror stands nearby.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The Oracle Lamp reveals a hidden passage behind the mirror.",
      "visual_description": "The Lamp’s flame flares, illuminating a crack in the wall behind the mirror; the Glass Diver taps the glass, and it swings open.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The Sleeping Tax Collector wakes and demands a stamp.",
      "visual_description": "The Tax Collector sits up, rubbing his eyes, and holds out a hand for a stamped permission slip before he will move further.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Mara stamps a paper using a fallen seal.",
      "visual_description": "Mara finds a cracked wax seal on the floor, presses it onto a scrap of paper, and hands it to the Tax Collector, who nods approvingly.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The group climbs a broken tower staircase.",
      "visual_description": "Stone steps spiral upward, some missing; the Tin Fox leaps gaps, and the Glass Diver uses reflections to check for danger above.",
      "characters": ["glass_diver", "tin_fox", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "They find the captive behind a cursed lock.",
      "visual_description": "At the tower top, a heavy door with a glowing lock bars the way; a faint voice calls from inside, and the Glass Diver peers through a crack.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The Glass Diver swims through a mirror to unlock the door from inside.",
      "visual_description": "The Glass Diver steps into a standing mirror, emerges in the locked room, and turns the deadbolt; the door swings open to cheers.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 18,
      "caption": "The rescue party escapes across a crumbling bridge.",
      "visual_description": "Under a bruised sky, the group hurries across a stone bridge with missing railings; behind them, the city crumbles; ahead, open land.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

